from typing import Dict, Mapping, Sequence, Tuple

def allocate_backorders(orders: Sequence[Tuple[str, int, int, Mapping[str, int]]], available: Mapping[str, int]) -> Dict[str, Dict[str, int]]:
    order_ids = [o[0] for o in orders]
    if len(set(order_ids)) != len(order_ids):
        raise ValueError("Duplicate order_id found")
    for order in orders:
        for sku, qty in order[3].items():
            if qty <= 0:
                raise ValueError(f"Line quantity for SKU {sku} in order {order[0]} must be > 0")
    stock = dict(available)
    sorted_orders = sorted(orders, key=lambda x: (x[1], x[2], x[0]))
    results = {}
    for oid, prio, day, lines in sorted_orders:
        can_fill = True
        for sku, qty in lines.items():
            if stock.get(sku, 0) < qty:
                can_fill = False
                break
        if can_fill:
            res_lines = {}
            for sku, qty in lines.items():
                res_lines[sku] = qty
                stock[sku] = stock.get(sku, 0) - qty
            results[oid] = res_lines
        else:
            results[oid] = {sku: 0 for sku in lines}
    return results"}}}
