        # We must find the stock for the SKU at the location that parses to from_parsed
        on_hand = 0
        for (s, loc), q in stock.items():
            if s == sku and parse_location(loc) == from_parsed:
                on_hand += q
        if on_hand < qty:
            problems.append("INSUFFICIENT_STOCK")

    return problems"}}}
