        # Only movements with day < transfer_day are counted.
        stock = on_hand_by_location(lines, case_sizes, as_of_day=day - 1)
        on_hand = 0
        for (s, loc), q in stock.items():
            if s == sku and parse_location(loc) == from_parsed:
                on_hand += q
        if on_hand < qty:
            problems.append("INSUFFICIENT_STOCK")

    return problems"}}}
